algorithm.rustSketch:
fn gcd(mut a: u64, mut b: u64) -> u64 {
    while b != 0 {
        (a, b) = (b, a % b);
    }
    a
}

fn main() {
    let result = gcd(12, 8).to_string();
    println!("{result}");
}

